INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 35, 'theory', 'Quiz: TypeScript, ESLint and Prettier');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 35, 0, 'What happens to TypeScript types at build time?', '["They become runtime checks", "They are erased: the output JavaScript has none", "They are kept in comments", "They are replaced with any"]', 1, 'Types exist only at check time. That is why data from outside has to be checked with validators.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 35, 1, 'How is type compatibility determined in TypeScript?', '["By the type''s name", "Structurally: a value with the needed fields of the needed types fits", "By the order of fields", "By the place of declaration"]', 1, 'Structural typing: shape matters, not the name; extra fields are allowed (except in fresh object literals).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 35, 2, 'What is the never type for when handling a union?', '["For switching checks off", "After all variants are handled, never remains: the compiler flags unhandled new variants", "For type casting", "For async functions"]', 1, 'Exhaustiveness checking: in the default branch the value has type never; a new union variant causes a compile error.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 35, 3, 'What does Prettier do, and what does ESLint do?', '["Prettier finds bugs, ESLint formats", "Prettier brings code to one format, ESLint finds errors and bad practices", "They do the same thing", "Both only check types"]', 1, 'Formatting is Prettier''s job; rule-based static analysis is ESLint''s. Conflicting ESLint style rules are turned off (eslint-config-prettier).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 35, 4, 'Why can''t you simply assign a type to a server response with as?', '["as is forbidden by the syntax", "as switches checking off: the compiler does not know the real data — you need unknown and validation", "as slows the code down", "Types don''t work with JSON"]', 1, 'The type is not checked at run time. At the boundary you accept unknown and check it with a type guard or zod.');
